<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no, viewport-fit=cover">
  <title><?= htmlspecialchars($SITE_TITLE ?? 'MartPoint'); ?> — Shipping Fees</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
  <link rel="stylesheet" href="<?= $theme_link; ?>css/font-awesome-4.7.0/css/font-awesome.min.css">
  <style>
    :root { --mp-primary:#0057FF; --mp-bg:#F1F5F9; --mp-surface:#fff; --mp-text:#0F172A; --mp-muted:#64748B; --mp-border:#E2E8F0; --mp-success:#059669; --mp-danger:#DC2626; --mp-warning:#EA580C; }
    * { box-sizing:border-box; } html,body { margin:0; min-height:100%; font-family:Inter,-apple-system,BlinkMacSystemFont,sans-serif; background:var(--mp-bg); color:var(--mp-text); }
    .screen { min-height:100vh; padding:12px 16px 160px; } .topbar { display:flex; align-items:center; gap:12px; margin-bottom:16px; padding-top:calc(8px + env(safe-area-inset-top, 0px)); }
    .back { color:var(--mp-primary); font-size:20px; text-decoration:none; } .topbar-titles { flex:1; min-width:0; } .store-name { color:var(--mp-muted); font-size:11px; font-weight:600; letter-spacing:.4px; overflow:hidden; text-overflow:ellipsis; text-transform:uppercase; white-space:nowrap; } h1 { margin:2px 0 0; font-size:22px; }
    .hint { background:#EFF6FF; border:1px solid #BFDBFE; border-radius:14px; color:#1E40AF; font-size:13px; line-height:1.5; margin-bottom:16px; padding:13px 14px; } .hint i { margin-right:6px; }
    .fee-list { display:grid; gap:10px; } .fee-card { background:var(--mp-surface); border:1px solid var(--mp-border); border-radius:14px; padding:14px; } .fee-head { align-items:flex-start; display:flex; gap:10px; } .fee-name { flex:1; font-size:16px; font-weight:700; } .fee-amount { color:var(--mp-success); font-size:16px; font-weight:700; white-space:nowrap; } .fee-location { color:var(--mp-muted); font-size:13px; margin-top:5px; } .fee-meta { align-items:center; border-top:1px solid var(--mp-border); display:flex; gap:10px; justify-content:space-between; margin-top:12px; padding-top:10px; } .status { border-radius:999px; font-size:11px; font-weight:700; padding:4px 8px; } .status.active { background:#D1FAE5; color:#047857; } .status.inactive { background:#E2E8F0; color:#475569; } .actions { display:flex; gap:8px; } .icon-button { background:#fff; border:1px solid var(--mp-border); border-radius:9px; color:var(--mp-primary); font-size:14px; min-height:36px; min-width:38px; } .icon-button.delete { color:var(--mp-danger); }
    .add { align-items:center; background:var(--mp-primary); border:0; border-radius:12px; bottom:104px; box-shadow:0 8px 20px rgba(0,87,255,.25); color:#fff; display:flex; font:600 14px inherit; gap:8px; padding:12px 16px; position:fixed; right:16px; z-index:200; } .empty { background:#fff; border:1px dashed var(--mp-border); border-radius:14px; color:var(--mp-muted); padding:28px 16px; text-align:center; }
    .sheet { background:rgba(15,23,42,.45); bottom:0; display:none; left:0; padding:16px; position:fixed; right:0; top:0; z-index:700; } .sheet.open { align-items:flex-end; display:flex; } .sheet-panel { background:#fff; border-radius:20px 20px 12px 12px; max-height:calc(100vh - 32px); overflow:auto; padding:20px 16px calc(20px + env(safe-area-inset-bottom,0px)); width:100%; } .sheet-title { align-items:center; display:flex; font-size:18px; font-weight:700; justify-content:space-between; margin-bottom:18px; } .close { background:transparent; border:0; color:var(--mp-muted); font-size:22px; } label { display:block; font-size:13px; font-weight:600; margin:14px 0 6px; } input[type=text], input[type=number] { border:1px solid var(--mp-border); border-radius:10px; font:inherit; min-height:45px; padding:10px 12px; width:100%; } .form-row { display:grid; gap:12px; grid-template-columns:1fr 1fr; } .toggle { align-items:center; display:flex; gap:8px; } .save { background:var(--mp-primary); border:0; border-radius:10px; color:#fff; font:600 15px inherit; margin-top:20px; min-height:46px; width:100%; }
  </style>
</head>
<body>
  <main class="screen">
    <header class="topbar"><a class="back" href="<?= base_url('mobile/more'); ?>" aria-label="Back"><i class="fa fa-chevron-left"></i></a><div class="topbar-titles"><div class="store-name"><?= htmlspecialchars($SITE_TITLE ?? 'MartPoint'); ?></div><h1>Shipping Fees</h1></div></header>
    <div class="hint"><i class="fa fa-truck"></i>Active locations appear at POS checkout. Their delivery charge is added to the sale total.</div>
    <section class="fee-list">
      <?php foreach($fees as $fee): ?><article class="fee-card" data-id="<?= (int)$fee->id; ?>" data-label="<?= htmlspecialchars($fee->label, ENT_QUOTES, 'UTF-8'); ?>" data-location="<?= htmlspecialchars($fee->location ?? '', ENT_QUOTES, 'UTF-8'); ?>" data-fee="<?= htmlspecialchars($fee->fee, ENT_QUOTES, 'UTF-8'); ?>" data-order="<?= (int)$fee->sort_order; ?>" data-enabled="<?= (int)$fee->is_enabled; ?>"><div class="fee-head"><div class="fee-name"><?= htmlspecialchars($fee->label); ?><div class="fee-location"><?= htmlspecialchars($fee->location ?: 'No area specified'); ?></div></div><div class="fee-amount"><?= $this->currency(store_number_format($fee->fee)); ?></div></div><div class="fee-meta"><span class="status <?= $fee->is_enabled ? 'active' : 'inactive'; ?>"><?= $fee->is_enabled ? 'Active at POS' : 'Inactive'; ?></span><?php if($can_add || $can_delete): ?><div class="actions"><?php if($can_add): ?><button class="icon-button" type="button" onclick="editFee(this.closest('.fee-card'))" aria-label="Edit shipping fee"><i class="fa fa-pencil"></i></button><?php endif; ?><?php if($can_delete): ?><button class="icon-button delete" type="button" onclick="deleteFee(<?= (int)$fee->id; ?>)" aria-label="Delete shipping fee"><i class="fa fa-trash"></i></button><?php endif; ?></div><?php endif; ?></div></article><?php endforeach; ?>
      <?php if(empty($fees)): ?><div class="empty"><i class="fa fa-truck fa-2x"></i><p>No shipping fees yet.</p><?php if($can_add): ?><span>Add your first delivery location.</span><?php endif; ?></div><?php endif; ?>
    </section>
    <?php if($can_add): ?><button class="add" type="button" onclick="openForm()"><i class="fa fa-plus"></i> Add Shipping Fee</button><?php endif; ?>
  </main>
  <div class="sheet" id="feeSheet" aria-hidden="true"><form class="sheet-panel" id="feeForm"><div class="sheet-title"><span id="formTitle">Add Shipping Fee</span><button class="close" type="button" onclick="closeForm()">&times;</button></div><input type="hidden" name="fee_id" id="fee_id"><input type="hidden" name="<?= $this->security->get_csrf_token_name(); ?>" value="<?= $this->security->get_csrf_hash(); ?>"><label for="f_label">Name *</label><input id="f_label" name="label" required placeholder="e.g. Lekki Delivery" type="text"><label for="f_location">Location / Area</label><input id="f_location" name="location" placeholder="e.g. Lekki Phase 1" type="text"><div class="form-row"><div><label for="f_fee">Fee *</label><input id="f_fee" name="fee" required min="0" step="0.01" type="number"></div><div><label for="f_order">Sort Order</label><input id="f_order" name="sort_order" value="0" type="number"></div></div><label class="toggle"><input id="f_enabled" name="is_enabled" checked type="checkbox"> Active (show in POS)</label><button class="save" type="submit">Save Shipping Fee</button></form></div>
  <?php $this->load->view('mobile/bottom_nav', ['active' => 'more']); ?>
  <?php $this->load->view('mobile/mp_alert'); ?>
  <?php $this->load->view('mobile/chat'); ?>
  <script>
    var sheet=document.getElementById('feeSheet'), form=document.getElementById('feeForm');
    function openForm(){ form.reset(); document.getElementById('fee_id').value=''; document.getElementById('f_enabled').checked=true; document.getElementById('formTitle').textContent='Add Shipping Fee'; sheet.classList.add('open'); sheet.setAttribute('aria-hidden','false'); }
    function closeForm(){ sheet.classList.remove('open'); sheet.setAttribute('aria-hidden','true'); }
    function editFee(card){ document.getElementById('fee_id').value=card.dataset.id; document.getElementById('f_label').value=card.dataset.label; document.getElementById('f_location').value=card.dataset.location; document.getElementById('f_fee').value=card.dataset.fee; document.getElementById('f_order').value=card.dataset.order; document.getElementById('f_enabled').checked=card.dataset.enabled==='1'; document.getElementById('formTitle').textContent='Edit Shipping Fee'; sheet.classList.add('open'); sheet.setAttribute('aria-hidden','false'); }
    sheet.addEventListener('click',function(e){ if(e.target===sheet) closeForm(); });
    form.addEventListener('submit',function(e){ e.preventDefault(); var button=form.querySelector('.save'); button.disabled=true; button.textContent='Saving…'; fetch('<?= base_url('shipping_fees/save'); ?>',{method:'POST',body:new FormData(form),credentials:'same-origin'}).then(function(r){return r.json();}).then(function(r){if(r.status==='success'){location.reload();return;} alert(r.message||'Unable to save this shipping fee.');}).catch(function(){alert('Unable to save this shipping fee. Check your connection and try again.');}).then(function(){button.disabled=false;button.textContent='Save Shipping Fee';}); });
    function deleteFee(id){ if(!confirm('Delete this shipping fee?')) return; var data=new FormData(); data.append('<?= $this->security->get_csrf_token_name(); ?>','<?= $this->security->get_csrf_hash(); ?>'); fetch('<?= base_url('shipping_fees/delete/'); ?>'+id,{method:'POST',body:data,credentials:'same-origin'}).then(function(r){return r.json();}).then(function(r){if(r.status==='success'){location.reload();return;}alert(r.message||'Unable to delete this shipping fee.');}).catch(function(){alert('Unable to delete this shipping fee.');}); }
  </script>
</body>
</html>
